void main() async { WidgetsFlutterBinding.ensureInitialized(); await Hive.initFlutter(); final store=TaskStore(); await store.load(); runApp(ChangeNotifierProvider.value(value:store,child:const TaskFlowApp())); }
class Task { Task({required this.id,required this.title,required this.project,required this.due,required this.priority,this.done=false}); final String id,title,project,priority; final DateTime due; bool done; Map<String,dynamic> toJson()=>{'id':id,'title':title,'project':project,'due':due.toIso8601String(),'priority':priority,'done':done}; factory Task.fromJson(Map d)=>Task(id:d['id'],title:d['title'],project:d['project'],due:DateTime.parse(d['due']),priority:d['priority'],done:d['done']); }
class TaskStore extends ChangeNotifier {late Box<String> box; List<Task> tasks=[]; List<String> projects=['Personal','Work']; Future<void> load()async{box=await Hive.openBox('taskflow');tasks=box.values.map((x)=>Task.fromJson(jsonDecode(x))).cast<Task>().toList();projects=[...{...projects,...tasks.map((t)=>t.project)}];notifyListeners();}Future<void> save()async{await box.clear();for(final t in tasks){await box.put(t.id,jsonEncode(t.toJson()));}notifyListeners();}Future<void> upsert(Task t)async{tasks.removeWhere((x)=>x.id==t.id);tasks.add(t);projects=[...{...projects,t.project}];await save();}Future<void> remove(Task t)async{tasks.remove(t);await save();}Future<void> demo()async{if(tasks.isNotEmpty)return;final n=DateTime.now();tasks=[Task(id:'1',title:'Prepare sprint notes',project:'Work',due:n,priority:'High'),Task(id:'2',title:'Morning run',project:'Personal',due:n,priority:'Medium',done:true),Task(id:'3',title:'Review pull request',project:'Work',due:n.add(const Duration(days:1)),priority:'High'),Task(id:'4',title:'Book dentist',project:'Personal',due:n.add(const Duration(days:3)),priority:'Low'),Task(id:'5',title:'Portfolio polish',project:'Work',due:n.add(const Duration(days:5)),priority:'Medium')];await save();}List<Task> get today=>tasks.where((t)=>DateUtils.isSameDay(t.due,DateTime.now())).toList();double get progress=>tasks.isEmpty?0:tasks.where((t)=>t.done).length/tasks.length; }
class TaskFlowApp extends StatelessWidget{const TaskFlowApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'TaskFlow',theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xff4f46e5)),useMaterial3:true,scaffoldBackgroundColor:const Color(0xfffafaff)),darkTheme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xffa5b4fc),brightness:Brightness.dark),useMaterial3:true),home:const Shell());}
class Shell extends StatefulWidget{const Shell({super.key});@override State<Shell> createState()=>_ShellState();}class _ShellState extends State<Shell>{int tab=0;final p=const[Home(),Tasks(),CalendarView(),Focus()];@override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:p[tab]),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const[NavigationDestination(icon:Icon(Icons.grid_view_outlined),label:'Today'),NavigationDestination(icon:Icon(Icons.checklist),label:'Tasks'),NavigationDestination(icon:Icon(Icons.calendar_month_outlined),label:'Calendar'),NavigationDestination(icon:Icon(Icons.timer_outlined),label:'Focus')]));}
class Home extends StatelessWidget{const Home({super.key});@override Widget build(BuildContext c){final s=c.watch<TaskStore>();return ListView(padding:const EdgeInsets.all(20),children:[Text(DateFormat('EEEE, MMMM d').format(DateTime.now()),style:const TextStyle(color:Colors.indigo)),const Text('Make today count.',style:TextStyle(fontSize:28,fontWeight:FontWeight.w800)),const SizedBox(height:20),Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xff4f46e5),Color(0xff8b5cf6)]),borderRadius:BorderRadius.circular(26)),child:Row(children:[SizedBox(width:76,height:76,child:Stack(fit:StackFit.expand,children:[CircularProgressIndicator(value:s.progress,strokeWidth:8,color:Colors.white,backgroundColor:Colors.white24),Center(child:Text('${(s.progress*100).round()}%',style:const TextStyle(color:Colors.white,fontWeight:FontWeight.bold)))])),const SizedBox(width:18),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Daily progress',style:TextStyle(color:Colors.white70)),Text('${s.tasks.where((t)=>t.done).length} of ${s.tasks.length} tasks complete',style:const TextStyle(color:Colors.white,fontSize:17,fontWeight:FontWeight.bold))]))])),const SizedBox(height:24),Text("Today's focus",style:Theme.of(c).textTheme.titleLarge),if(s.today.isEmpty) DemoButton(onPressed:s.demo)else ...s.today.map((t)=>TaskCard(t:t)),const SizedBox(height:20),Text('Weekly activity',style:Theme.of(c).textTheme.titleLarge),SizedBox(height:150,child:BarChart(BarChartData(titlesData:const FlTitlesData(show:false),borderData:FlBorderData(show:false),barGroups:List.generate(7,(i){final d=DateTime.now().subtract(Duration(days:6-i));final v=s.tasks.where((t)=>DateUtils.isSameDay(t.due,d)&&t.done).length.toDouble();return BarChartGroupData(x:i,barRods:[BarChartRodData(toY:v+0.15,color:const Color(0xff8b5cf6),width:14,borderRadius:BorderRadius.circular(8))]);})))])]);}}
class Tasks extends StatefulWidget{const Tasks({super.key});@override State<Tasks> createState()=>_TasksState();}class _TasksState extends State<Tasks>{String q='';String filter='All';@override Widget build(BuildContext c){final s=c.watch<TaskStore>();final list=s.tasks.where((t)=>(filter=='All'||(filter=='Done'?t.done:t.priority==filter))&&t.title.toLowerCase().contains(q.toLowerCase())).toList()..sort((a,b)=>a.due.compareTo(b.due));return Scaffold(floatingActionButton:FloatingActionButton.extended(onPressed:()=>editTask(c,null),icon:const Icon(Icons.add),label:const Text('New task')),body:ListView(padding:const EdgeInsets.all(20),children:[Text('All tasks',style:Theme.of(c).textTheme.headlineMedium),const SizedBox(height:14),TextField(onChanged:(x)=>setState(()=>q=x),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Search tasks',border:OutlineInputBorder(borderRadius:BorderRadius.all(Radius.circular(18)))),),const SizedBox(height:12),SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:['All','High','Medium','Low','Done'].map((x)=>Padding(padding:const EdgeInsets.only(right:8),child:ChoiceChip(label:Text(x),selected:filter==x,onSelected:(_)=>setState(()=>filter=x)))).toList())),const SizedBox(height:12),if(list.isEmpty)DemoButton(onPressed:s.demo)else ...list.map((t)=>TaskCard(t:t)),const SizedBox(height:90)]));}}
class TaskCard extends StatelessWidget{const TaskCard({super.key,required this.t});final Task t;@override Widget build(BuildContext c){final color={'High':Colors.red,'Medium':Colors.orange,'Low':Colors.teal}[t.priority]!;return Card(child:ListTile(onTap:()=>editTask(c,t),leading:Checkbox(value:t.done,onChanged:(v){t.done=v??false;c.read<TaskStore>().save();}),title:Text(t.title,style:TextStyle(decoration:t.done?TextDecoration.lineThrough:null,fontWeight:FontWeight.w600)),subtitle:Text('${t.project} · ${DateFormat.MMMd().format(t.due)}'),trailing:Container(padding:const EdgeInsets.symmetric(horizontal:8,vertical:4),decoration:BoxDecoration(color:color.withValues(alpha:.12),borderRadius:BorderRadius.circular(10)),child:Text(t.priority,style:TextStyle(color:color,fontSize:11,fontWeight:FontWeight.bold))));}}
class CalendarView extends StatefulWidget{const CalendarView({super.key});@override State<CalendarView> createState()=>_CalendarViewState();}class _CalendarViewState extends State<CalendarView>{DateTime selected=DateTime.now();@override Widget build(BuildContext c){final s=c.watch<TaskStore>();final days=List.generate(35,(i)=>DateTime(selected.year,selected.month,1).add(Duration(days:i)));final filtered=s.tasks.where((t)=>DateUtils.isSameDay(t.due,selected)).toList();return ListView(padding:const EdgeInsets.all(20),children:[Row(children:[IconButton(onPressed:()=>setState(()=>selected=DateTime(selected.year,selected.month-1,1)),icon:const Icon(Icons.chevron_left)),Expanded(child:Text(DateFormat.yMMMM().format(selected),textAlign:TextAlign.center,style:Theme.of(c).textTheme.titleLarge)),IconButton(onPressed:()=>setState(()=>selected=DateTime(selected.year,selected.month+1,1)),icon:const Icon(Icons.chevron_right))]),GridView.builder(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),itemCount:days.length,gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:7),itemBuilder:(_,i){final d=days[i];final active=d.month==selected.month;final has=s.tasks.any((t)=>DateUtils.isSameDay(t.due,d));return InkWell(onTap:()=>setState(()=>selected=d),child:Container(margin:const EdgeInsets.all(3),decoration:BoxDecoration(color:DateUtils.isSameDay(d,selected)?Colors.indigo:Colors.transparent,borderRadius:BorderRadius.circular(12)),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Text('${d.day}',style:TextStyle(color:DateUtils.isSameDay(d,selected)?Colors.white:active?null:Colors.grey)),if(has)Icon(Icons.circle,size:5,color:DateUtils.isSameDay(d,selected)?Colors.white:Colors.deepPurple)])));}),const SizedBox(height:18),Text('Tasks on ${DateFormat.MMMd().format(selected)}',style:Theme.of(c).textTheme.titleLarge),if(filtered.isEmpty)const Padding(padding:EdgeInsets.all(18),child:Text('No deadlines on this date.'))else ...filtered.map((t)=>TaskCard(t:t))]);}}
class Focus extends StatefulWidget{const Focus({super.key});@override State<Focus> createState()=>_FocusState();}class _FocusState extends State<Focus>{int seconds=25*60;Timer? timer;bool running=false;@override void dispose(){timer?.cancel();super.dispose();}void run(){setState(()=>running=!running);if(running){timer=Timer.periodic(const Duration(seconds:1),(x){if(seconds==0){x.cancel();setState(()=>running=false);return;}setState(()=>seconds--);});}else{timer?.cancel();}}@override Widget build(BuildContext c)=>Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Text('POMODORO',style:TextStyle(letterSpacing:2,color:Theme.of(c).colorScheme.primary)),Text('${(seconds~/60).toString().padLeft(2,'0')}:${(seconds%60).toString().padLeft(2,'0')}',style:const TextStyle(fontSize:68,fontWeight:FontWeight.w200)),const SizedBox(height:20),FilledButton.icon(onPressed:run,icon:Icon(running?Icons.pause:Icons.play_arrow),label:Text(running?'Pause focus':'Start 25 minute focus')),TextButton(onPressed:(){timer?.cancel();setState((){seconds=25*60;running=false;});},child:const Text('Reset timer'))]));}
