void editTask(BuildContext c,Task? old){final form=GlobalKey<FormState>();final title=TextEditingController(text:old?.title);String project=old?.project??'Personal',priority=old?.priority??'Medium';DateTime due=old?.due??DateTime.now();showModalBottomSheet(context:c,isScrollControlled:true,builder:(ctx)=>Padding(padding:EdgeInsets.fromLTRB(20,20,20,20+MediaQuery.of(ctx).viewInsets.bottom),child:StatefulBuilder(builder:(ctx,set)=>Form(key:form,child:Wrap(children:[Text(old==null?'Create task':'Edit task',style:Theme.of(ctx).textTheme.titleLarge),TextFormField(controller:title,decoration:const InputDecoration(labelText:'Task name'),validator:(v)=>v==null||v.trim().isEmpty?'Add a task name':null),DropdownButtonFormField(value:project,items:c.read<TaskStore>().projects.map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>set(()=>project=v!)),DropdownButtonFormField(value:priority,items:['High','Medium','Low'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>set(()=>priority=v!)),ListTile(title:Text('Due ${DateFormat.yMMMd().format(due)}'),trailing:const Icon(Icons.calendar_today),onTap:()async{final d=await showDatePicker(context:ctx,firstDate:DateTime.now().subtract(const Duration(days:365)),lastDate:DateTime.now().add(const Duration(days:3650)),initialDate:due);if(d!=null)set(()=>due=d);}),Row(children:[if(old!=null)TextButton(onPressed:()async{await c.read<TaskStore>().remove(old);if(ctx.mounted)Navigator.pop(ctx);},child:const Text('Delete',style:TextStyle(color:Colors.red))),const Spacer(),FilledButton(onPressed:()async{if(!form.currentState!.validate())return;await c.read<TaskStore>().upsert(Task(id:old?.id??DateTime.now().microsecondsSinceEpoch.toString(),title:title.text,project:project,due:due,priority:priority,done:old?.done??false));if(ctx.mounted)Navigator.pop(ctx);},child:const Text('Save'))])]))));}
